changeSet.sql:
CREATE TABLE portal_department (id uuid primary key, name varchar(100) not null unique, description varchar(500));
CREATE TABLE portal_work_profile (id uuid primary key, employee_id uuid not null unique references core_employee(uuid), department_id uuid references portal_department(id), job_title varchar(255), location varchar(255), work_mode varchar(255), avatar_color varchar(255));
CREATE TABLE portal_contract (id uuid primary key, employee_id uuid not null references core_employee(uuid), number varchar(255) not null unique, type varchar(255), status varchar(255), start_date date, end_date date, salary numeric(38,2), currency varchar(255), notes varchar(4000));
CREATE TABLE portal_document_template (id uuid primary key, name varchar(255) not null, category varchar(255), body varchar(12000));
CREATE TABLE portal_activity (id uuid primary key, title varchar(255), detail varchar(255), kind varchar(255), employee_id uuid, occurred_at timestamptz);
CREATE TABLE portal_holiday (id uuid primary key, date date not null unique, name varchar(255) not null);
ALTER TABLE abs_absence_request ADD COLUMN reason varchar(1000);
CREATE UNIQUE INDEX portal_employee_personal_id ON core_employee(personal_id) WHERE personal_id IS NOT NULL AND personal_id <> '';
